7630      private void castToTypeBelow(Expr expr, Type declared) {
7631          if (!(declared instanceof TraitType || declared instanceof VarType)) return;
7632          Option<Type> ot = expr.getInfo().getExprType();
7633          if (ot.isNone()) return;
7634          Type t = ot.unwrap();
7635          if (t instanceof com.sun.fortress.nodes.UnionType) {
7636              // A typecase has the union of its arms' types: self's type where each arm has it.
7637              Type one = null;
7638              for (Type e : ((com.sun.fortress.nodes.UnionType) t).getElements()) {
7639                  if (e instanceof BottomType) continue;
7640                  if (one != null && !one.equals(e)) return;
7641                  one = e;
7642              }
7643              t = one;
7644          }
7645          if (!(t instanceof TraitSelfType)) return;
7646          TraitSelfType self_t = (TraitSelfType) t;
7647          Type apparent = self_t.getNamed();
7648          if (self_t.getComprised().isEmpty() || !(apparent instanceof TraitType)) return;
7649          if (typeAnalyzer.opensSizes(apparent)) return;
7650          if (typeAnalyzer.lteq(apparent, declared) || !typeAnalyzer.lteq(declared, apparent)) return;
7651          String cast_to = NamingCzar.jvmTypeDesc(declared, thisApi(), false, true);
7652          InstantiatingClassloader.generalizedCastTo(mv, cast_to);
7653      }

